// Asks Administrate for every contact with a conflict between today and today + WINDOW_DAYS.
// Administrate works the conflicts out itself: sessions that overlap and sessions during an absence.
const cfg_obj = $('Config').first().json;
const days_num = Math.max(1, Number(cfg_obj.WINDOW_DAYS) || 30);
const from_str = $now.toISODate();
const to_str = $now.plus({ days: days_num }).toISODate();
const query_str = 'query ReadConflicts($from: Date!, $to: Date!) { contactConflicts(rangeStartDate: $from, rangeEndDate: $to) { conflictCount contact { id emailAddress personalName { firstName lastName } } sessions { id code title start end eventId conflicts { bookingType title start end unconfirmed } } } }';
return [{ json: { from: from_str, to: to_str, body: { query: query_str, variables: { from: from_str, to: to_str } } } }];

// Groups the conflicts by instructor and by date and builds one HTML email.
// Returns nothing when there is no conflict, so no email is sent.
const cfg_obj = $('Config').first().json;
const range_obj = $('Build Query').first().json;
const res_obj = $input.first().json || {};
if (res_obj.errors || !res_obj.data || !Array.isArray(res_obj.data.contactConflicts)) {
  throw new Error('Reading conflicts failed: ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 500));
}
const esc_fn = function (v_any) { return String(v_any === null || v_any === undefined ? '' : v_any).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); };
const when_fn = function (s_str) { const d_obj = DateTime.fromISO(String(s_str || ''), { setZone: true }); return d_obj.isValid ? d_obj : null; };
// Shows the full date, or only the times when it falls on the same day as ref_str.
const span_fn = function (a_str, b_str, ref_str) {
  const a_obj = when_fn(a_str); const b_obj = when_fn(b_str); const r_obj = ref_str ? when_fn(ref_str) : null;
  if (!a_obj) { return esc_fn(a_str); }
  const end_str = b_obj ? (b_obj.hasSame(a_obj, 'day') ? b_obj.toFormat('HH:mm') : b_obj.toFormat('ccc d LLL HH:mm')) : '';
  const start_str = r_obj && r_obj.hasSame(a_obj, 'day') ? a_obj.toFormat('HH:mm') : a_obj.toFormat('ccc d LLL yyyy, HH:mm');
  return start_str + (end_str ? ' to ' + end_str : '');
};
const includeUnconfirmed_bool = cfg_obj.INCLUDE_UNCONFIRMED !== false;
const urlTemplate_str = String(cfg_obj.EVENT_URL_TEMPLATE || '');
const people_ary = [];
let total_num = 0;
for (const c_obj of res_obj.data.contactConflicts) {
  const name_obj = (c_obj.contact || {}).personalName || {};
  const name_str = ((name_obj.firstName || '') + ' ' + (name_obj.lastName || '')).trim() || ((c_obj.contact || {}).emailAddress || 'Unknown contact');
  const rows_ary = [];
  for (const s_obj of (c_obj.sessions || [])) {
    const seen_obj = {};
    const with_ary = [];
    for (const k_obj of (s_obj.conflicts || [])) {
      if (k_obj.unconfirmed && !includeUnconfirmed_bool) { continue; }
      const key_str = [k_obj.bookingType, k_obj.title, k_obj.start, k_obj.end].join('|');
      if (seen_obj[key_str]) { continue; }
      seen_obj[key_str] = true;
      with_ary.push(k_obj);
    }
    if (with_ary.length === 0) { continue; }
    rows_ary.push({ session: s_obj, conflicts: with_ary, sortKey: String(s_obj.start || '') });
  }
  if (rows_ary.length === 0) { continue; }
  rows_ary.sort(function (a_obj, b_obj) { return a_obj.sortKey < b_obj.sortKey ? -1 : (a_obj.sortKey > b_obj.sortKey ? 1 : 0); });
  total_num += rows_ary.length;
  people_ary.push({ name: name_str, rows: rows_ary, first: rows_ary[0].sortKey });
}
if (people_ary.length === 0) { return []; }
people_ary.sort(function (a_obj, b_obj) { return a_obj.first < b_obj.first ? -1 : (a_obj.first > b_obj.first ? 1 : 0); });
const block_ary = people_ary.map(function (p_obj) {
  const trs_str = p_obj.rows.map(function (r_obj) {
    const s_obj = r_obj.session;
    const link_str = urlTemplate_str && urlTemplate_str.indexOf('YOUR-INSTANCE') < 0 ? urlTemplate_str.split('{id}').join(encodeURIComponent(s_obj.eventId)) : '';
    const label_str = esc_fn(s_obj.code) + ' &middot; ' + esc_fn(s_obj.title);
    const what_str = r_obj.conflicts.map(function (k_obj) {
      const kind_str = k_obj.bookingType === 'absence' ? 'Absence' : (k_obj.bookingType === 'session' ? 'Another session' : esc_fn(k_obj.bookingType));
      return '<div style="margin:2px 0;">' + kind_str + ': <strong>' + esc_fn(k_obj.title || 'untitled') + '</strong> (' + span_fn(k_obj.start, k_obj.end, s_obj.start) + ')' + (k_obj.unconfirmed ? ' <span style="color:#8A5A00;">unconfirmed</span>' : '') + '</div>';
    }).join('');
    return '<tr><td style="padding:10px 12px;border-top:1px solid #E6EAF0;vertical-align:top;white-space:nowrap;font-size:13px;color:#16202B;">' + span_fn(s_obj.start, s_obj.end) + '</td><td style="padding:10px 12px;border-top:1px solid #E6EAF0;vertical-align:top;font-size:13px;color:#16202B;">' + (link_str ? '<a href="' + esc_fn(link_str) + '" style="color:' + esc_fn(cfg_obj.BRAND_COLOUR) + ';">' + label_str + '</a>' : label_str) + '<div style="margin-top:4px;color:#5A6472;">' + what_str + '</div></td></tr>';
  }).join('');
  return '<h3 style="margin:24px 0 6px;font-size:15px;color:#16202B;">' + esc_fn(p_obj.name) + ' <span style="font-weight:normal;color:#5A6472;">(' + p_obj.rows.length + ' session' + (p_obj.rows.length > 1 ? 's' : '') + ')</span></h3><table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' + trs_str + '</table>';
}).join('');
const from_label = DateTime.fromISO(range_obj.from).toFormat('d LLL yyyy');
const to_label = DateTime.fromISO(range_obj.to).toFormat('d LLL yyyy');
const html_str = '<div style="font-family:Arial,Helvetica,sans-serif;background:#F4F6F8;padding:24px;"><table width="680" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:8px;"><tr><td style="background:' + esc_fn(cfg_obj.BRAND_COLOUR) + ';padding:18px 24px;color:#FFFFFF;font-size:18px;font-weight:bold;">' + esc_fn(cfg_obj.BRAND_NAME) + '</td></tr><tr><td style="padding:24px;"><p style="margin:0 0 4px;font-size:16px;color:#16202B;"><strong>' + total_num + ' session' + (total_num > 1 ? 's' : '') + ' with an instructor conflict</strong> across ' + people_ary.length + ' instructor' + (people_ary.length > 1 ? 's' : '') + '</p><p style="margin:0;font-size:13px;color:#5A6472;">From ' + from_label + ' to ' + to_label + '. Each line is a session the instructor is booked on while also booked elsewhere or recorded as absent.</p>' + block_ary + '</td></tr></table></div>';
const subject_str = (cfg_obj.EMAIL_SUBJECT_PREFIX || 'Instructor availability conflicts') + ': ' + total_num + ' session' + (total_num > 1 ? 's' : '') + ', ' + people_ary.length + ' instructor' + (people_ary.length > 1 ? 's' : '');
return [{ json: { subject: subject_str, html: html_str, sessions: total_num, instructors: people_ary.map(function (p_obj) { return p_obj.name; }) } }];

// The email goes through Administrate, so each recipient must be an Administrate contact.
const cfg_obj = $('Config').first().json;
const emails_ary = String(cfg_obj.RECIPIENT_EMAILS || '').split(',').map(function (e_str) { return e_str.trim().toLowerCase(); }).filter(Boolean);
if (emails_ary.length === 0) { throw new Error('RECIPIENT_EMAILS is empty in the Config node.'); }
const parts_ary = emails_ary.map(function (e_str, i_num) { return 'r' + i_num + ': contacts(first: 2, filters: [{ field: emailAddress, operation: eq, value: ' + JSON.stringify(e_str) + ' }]) { edges { node { id emailAddress } } }'; });
return [{ json: { emails: emails_ary, body: { query: 'query FindRecipients { ' + parts_ary.join(' ') + ' }' } } }];

// One item per recipient contact. Stops with a clear message if an address is not a contact.
const emails_ary = $('Build Recipient Query').first().json.emails;
const digest_obj = $('Build Digest').first().json;
const res_obj = $input.first().json || {};
if (res_obj.errors || !res_obj.data) { throw new Error('Looking up recipients failed: ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 300)); }
const missing_ary = [];
const out_ary = [];
emails_ary.forEach(function (e_str, i_num) {
  const edges_ary = ((res_obj.data['r' + i_num] || {}).edges) || [];
  if (edges_ary.length === 0) { missing_ary.push(e_str); return; }
  out_ary.push({ json: { contactId: edges_ary[0].node.id, email: e_str, subject: digest_obj.subject, html: digest_obj.html } });
});
if (missing_ary.length > 0) { throw new Error('No Administrate contact found for: ' + missing_ary.join(', ') + '. Each recipient needs a contact record.'); }
return out_ary;

const rec_obj = $('Resolve Recipients').item.json;
const res_obj = $json || {};
const send_obj = ((res_obj.data || {}).contactAdhocEmails || {}).sendContactAdhocEmail;
const errs_ary = (res_obj.errors || []).concat((send_obj && send_obj.errors) || []);
if (!send_obj || errs_ary.length > 0) {
  throw new Error('The digest could not be sent to ' + rec_obj.email + ': ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'missing response'));
}
return { json: { sentTo: rec_obj.email } };
